import{_ as t,o as a,c as l,a2 as c}from"./chunks/framework.BXA5Pi9t.js";const k=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-05-27","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-05-27","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-27.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-27.md","lastUpdated":null}'),o={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-05-27.md"};function i(r,e,u,s,b,n){return a(),l("div",null,[...e[0]||(e[0]=[c('<p>I&#39;m ready to create the meeting summary in Chinese following the specified format.--- title: Ceph RGW Refactoring Meeting 2026-05-27 date: 2026-07-10 updated: 2026-07-11 tags:</p><ul><li>RGW</li><li>对象存储</li><li>会议纪要</li><li>存储优化 categories:</li><li>视频总结 subtitle: Ceph_RGW_Refactoring_Meeting_2026-05-27</li></ul><hr><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph RGW Refactoring 会议围绕两个主题展开：一是 Yuval 提出的 vector bucket（向量桶）与常规 S3 bucket 之间关系的重新设计，二是 umbrella 版本冻结日期及相关 blocker（阻塞项）的更新。会议由 Casey 主持，Yuval、Soumya 等成员参与讨论。</p><h2 id="主题一-vector-bucket-与-s3-bucket-的关系重构" tabindex="-1">主题一：Vector Bucket 与 S3 Bucket 的关系重构 <a class="header-anchor" href="#主题一-vector-bucket-与-s3-bucket-的关系重构" aria-label="Permalink to &quot;主题一：Vector Bucket 与 S3 Bucket 的关系重构&quot;">​</a></h2><h3 id="背景回顾" tabindex="-1">背景回顾 <a class="header-anchor" href="#背景回顾" aria-label="Permalink to &quot;背景回顾&quot;">​</a></h3><p>Yuval 重新提起了几个月前讨论过的议题：vector bucket 用于保存向量（vectors）和索引（indexes），但它并不把这些内容当作普通 object 来存储，而是在后端通过一层抽象来实现。这层后端实际上使用了一个常规的 S3 bucket 来以 object 的形式保存向量等数据，但并非一对一映射的关系。</p><p>此前的方案是：为每个 vector bucket 关联一个常规 S3 bucket 用于存放实际数据，但这个常规 bucket 必须对用户隐藏。原因在于：</p><ul><li>该 bucket 由内部使用的 LanceDB 实现来操作其中的 object，用户不应触碰甚至读取它。</li><li>由此带来一系列难题：谁负责创建这个常规 S3 bucket？是否自动创建？如何对用户隐藏？权限（permissions）如何设置？</li></ul><h3 id="新的简化方案" tabindex="-1">新的简化方案 <a class="header-anchor" href="#新的简化方案" aria-label="Permalink to &quot;新的简化方案&quot;">​</a></h3><p>Yuval 从某个 PR 中的一处 hack 得到启发：实际上可以直接用 vector bucket 本身来存储 object。这个 hack 的做法是，在代码里把 vector bucket 当作常规 bucket 加载（调用 SAL 的 load bucket 函数并传入 vector bucket 的标识），从而能够在其中创建 object。</p><p>据此，Yuval 提出一个更加自包含（self-contained）的方案：</p><ul><li>从前端（front-end）视角看，vector bucket 仍然是 vector bucket——它不出现在 bucket 列表中，无法被 list、get object、put object 等 REST 操作访问。</li><li>但在 RGW 代码内部，可以对它执行所有这些操作，让它像一个带 object 的常规 bucket 一样工作，用自身来存储所需的全部信息。</li></ul><p>该方案需要修改 Yuval 原先的实现。例如，原实现里这个 bucket 没有 bucket index，这一点可能需要调整。但总体上，这会是一个更好的自包含解决方案，既能利用 bucket 真正的 object 存储能力和全部 API，同时又对用户保持隐藏，不暴露任何 REST 命令。</p><h3 id="隐藏机制与命名空间-namespace" tabindex="-1">隐藏机制与命名空间（Namespace） <a class="header-anchor" href="#隐藏机制与命名空间-namespace" aria-label="Permalink to &quot;隐藏机制与命名空间（Namespace）&quot;">​</a></h3><p>Casey 询问隐藏机制的原理。Yuval 说明：</p><ul><li>在 SAL 层，这一切本就能工作（如今那个 hack 已经证明可行）。</li><li>但由于 bucket 的创建走的是 vector bucket 专用的创建流程，因此不会更新用户的 bucket 列表——执行 list bucket 时看不到它。</li><li>它也不实现任何 get object / put object 的 REST 操作，因为它属于不同的 namespace，带有特定前缀。若用户用 vector bucket 的名字去 put object，系统会因命名空间不同而找不到它。</li></ul><p>Casey 将其归纳为：这是对 bucket entry point object 做 namespacing，使其只能通过 vector API 以特定格式访问，而 S3 API 无法访问；LanceDB 后端知道该用哪个命名空间。Yuval 确认，并补充说：在 RADOS 层面观察，它看起来就是一个普通 bucket，但这个 bucket 仅供 admin 用途，普通用户不应使用。</p><h3 id="后端设计-直接对接-sal" tabindex="-1">后端设计：直接对接 SAL <a class="header-anchor" href="#后端设计-直接对接-sal" aria-label="Permalink to &quot;后端设计：直接对接 SAL&quot;">​</a></h3><p>Casey 回顾早先曾设想让后端走 S3 REST API，最终再转换到 RADOS 或 SAL。Yuval 说明当时之所以有此设想，是因为不确定如何把 SAL 接入作为 LanceDB 的后端。但 Soumya 已经解决了这个关键难题：</p><ul><li>她掌握了如何创建一个自定义的 object store 后端注册表（registry），可以把 S3、GCP 等 URL 名称映射到特定实现。</li><li>她将其映射到自己的实现，即 cell（SAL 层）。LanceDB 的 object store 基类包含 put object、get object、multi-part upload、conditional write 等各类方法，她在底层把这个 Rust 库映射到对应的 cell 函数。</li></ul><p>由于这块拼图已经打通，团队可以直接跳到 cell 实现，既更高效，从可用性（usability）角度也更简单——无需创建 bucket、无需保证权限正确，一切都是自包含的。Casey 认可这一方向，并指出这样一来就不再需要依赖 tenant 之类的机制来隐藏 bucket，共享一个 bucket 实例的做法是可行的。</p><h3 id="待解决问题-quota-配额-管理" tabindex="-1">待解决问题：Quota（配额）管理 <a class="header-anchor" href="#待解决问题-quota-配额-管理" aria-label="Permalink to &quot;待解决问题：Quota（配额）管理&quot;">​</a></h3><p>这是本主题唯一遗留的开放问题，既有利也有弊：</p><ul><li>有利的一面：因为它就是一个 bucket，拥有全部 quota API，配额管理理应直接可用。</li><li>不利的一面：需要决定如何处理索引。索引也是以 object 形式存储在同一个 bucket 中。当用户执行 put vector（类似 put object）时，他们预期这会消耗空间；但如果系统为了更快的检索和查询而替用户创建索引，这些索引同样会消耗空间，其计费策略尚不明确。</li></ul><p>Casey 指出关键冲突点：由于这些 bucket 被从用户的 <code>user.buckets</code> 列表中隐藏，而 user 和 account 的 quota 恰恰依赖这份用户/账户拥有的 bucket 列表来汇总用量。Yuval 确认 vector bucket 侧有一份类似的列表（每种 head 有不同前缀），因此需要修改 per-user 或 per-account 的配额管理实现。Casey 建议查看 <code>rgw_quota.cc</code>，其中有汇总 user/account bucket 的逻辑，可以扩展它以同时统计 vector bucket。</p><p>关于索引是否计入配额，Casey 明确表态：只要是替用户消耗了存储容量，即便只是内部优化用途，也应计入其 quota。Yuval 表示可以据此扩展 admin 报告的输出，让统计更清晰。</p><p>关于用量的细分统计，双方讨论到：</p><ul><li>当前 bucket index 只是把所有 object 的用量加总；有一项进行中的工作是按 storage class 分别统计，但 storage class 并不适合 vector 这个场景。</li><li>若通过 cell API 上传，需要让 cell 层能够区分普通 object 与索引 object。</li><li>第一版方案：先把所有用量合并统计，但可以区分 S3 消耗与 S3 vector 消耗（因为二者是不同的列表，可以拆分）。</li></ul><p>关于未来的 storage class：Yuval 认为对 vector 场景 storage class 未来可能有意义，因为索引需要比向量更快的检索——查询时先加载索引，再据此确定要获取哪些向量。因此可能希望把索引放在更快的介质上。Casey 提醒，如果为此设立一个专门的 storage class 作为全局配置，用户就有可能往里上传自己的 object，所以也许不宜采用；这属于未来讨论范畴。</p><h2 id="主题二-umbrella-版本冻结日期与-blocker-更新" tabindex="-1">主题二：Umbrella 版本冻结日期与 Blocker 更新 <a class="header-anchor" href="#主题二-umbrella-版本冻结日期与-blocker-更新" aria-label="Permalink to &quot;主题二：Umbrella 版本冻结日期与 Blocker 更新&quot;">​</a></h2><p>Casey 通报，Patrick 已将 umbrella 的 freeze date（冻结日期）推后到 6 月 5 日。RGW 目前跟踪的 blocker 有两项：</p><ol><li><strong>GCM encryption（加密）</strong>：Casey 刚刚开始对其进行 QA。</li><li><strong>Adam 对 OMAP data logs（原表述为 BI logs，后更正为 data logs）的 deprecation（废弃）</strong>。</li></ol><p>会上还确认了一项新的 blocker：Yuval 提出 Lua packages 特性去重（duplication）相关的改动是 umbrella 所需的。该改动细节：</p><ul><li>尚未完成，但改动本身较为直接——把一个 CMake 宏从默认开启改为默认关闭。</li><li>这是一个 breaking change（破坏性变更），对 release notes 影响较大，需要谨慎措辞。</li><li>本质上是移除默认支持：下游（downstream）若需要仍可自行启用，但官方镜像不再包含该功能。</li><li>之所以要移除，是出于安全（security）方面的考虑。</li></ul><p>Casey 强调：由于涉及安全问题，请 Yuval 尽快把 PR 提交并整理到位，然后在 Slack 上 ping 他——因为要成为 blocker 必须先有对应的 PR。Yuval 答应尽快处理。</p><p>关于 umbrella 的收口策略，会上澄清：此时只允许 blocker 类 issue 进入；bug fix 仍可 backport 进 umbrella，但对于 feature、deprecation 等则以本次为硬性截止期限。因此本次会议讨论的重点是——哪些 feature 应被视为 blocker，而非一般 feature。</p><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ul><li>采用自包含方案：vector bucket 用自身存储向量与索引数据，废弃此前&quot;额外关联一个隐藏 S3 bucket&quot;的思路。</li><li>后端直接对接 SAL（cell）实现，不再走 S3 REST API 再转换的路径。</li><li>隐藏机制通过 namespace 前缀实现：vector bucket 不进入用户 bucket 列表，也不暴露 get/put object 等 REST 操作。</li><li>索引所占存储容量应计入用户 quota。</li><li>第一版配额统计先合并计算，但区分 S3 消耗与 S3 vector 消耗两份列表。</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>Yuval：修改原实现以支持在 vector bucket 内直接存储 object（涉及补充 bucket index 等）。</li><li>Yuval：修改 per-user / per-account 配额管理逻辑，参考 <code>rgw_quota.cc</code>，扩展其 bucket 汇总以纳入 vector bucket。</li><li>Yuval：尽快提交 Lua packages 去重相关的 PR（把 CMake 宏默认值由 on 改为 off），措辞好 release notes 中的 breaking change 说明，完成后在 Slack 上通知 Casey；并将该项加入 Patrick 的 blocker 列表。</li><li>Casey：继续对 GCM encryption 进行 QA；跟踪 Adam 对 OMAP data logs 的 deprecation。</li><li>未来事项：考虑为索引数据引入独立的用量统计乃至专用 storage class（放置于更快介质），但需规避用户借此上传自有 object 的风险。</li></ul>',42)])])}const d=t(o,[["render",i]]);export{k as __pageData,d as default};
